    const bytes = typeof jsonTextOrBytes === 'string'
        ? new TextEncoder().encode(jsonTextOrBytes)
        : jsonTextOrBytes;
    if (bytes.byteLength > limits.maxInputBytes) {
        throw new MsfPdfError('LIMIT_EXCEEDED', 'JSON payload exceeds maxInputBytes ceiling');
    }
    let parsed;
    try {
        const str = typeof jsonTextOrBytes === 'string'
            ? jsonTextOrBytes
            : new TextDecoder().decode(bytes);
        parsed = JSON.parse(str);
    }
    catch (err) {
        throw new MsfPdfError('INVALID_SPEC', `malformed JSON specification: ${err instanceof Error ? err.message : String(err)}`);
    }
